{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "The bill would add charter schools to wording in Sections 49-3-103(d)(3) and 49-3-316(c).",
      "rationale": "Identifies the amended provision and conveys its extension to public charter schools."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "The state would send a charter school the state share of funding generated by its students, rather than sending that share to the local education agency (LEA). Other student-generated funding would go to the LEA while the student is a member, except for funding under a cited provision that the department would retain.",
      "rationale": "Conveys the general allocation rule and direct charter-school payment, but does not identify subdivision (c)(3) as the funding the department must retain."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "Other student-generated funding would go to the LEA while the student is a member, except for funding under a cited provision that the department would retain. For funding purposes, a student who graduates early would remain a member until the student’s expected graduation date.",
      "rationale": "Conveys funding throughout actual membership and the extension through an early graduate's expected graduation date."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The bill would add charter schools to wording in Sections 49-3-103(d)(3) and 49-3-316(c).",
      "rationale": "Identifies subsection 49-3-316(c) and conveys its extension to charter schools."
    },
    {
      "proposition_id": "P5",
      "status": "partial",
      "summary_quote": "It would also require the education commissioner, in consultation with the comptroller, to establish a standardized charter-school financial accounting and reporting system",
      "rationale": "Includes the responsible officials and standardized system, but omits necessary revisions, forms or documentation, comparative design requirements, and accounting for all sources and uses of funds."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "It would also require the education commissioner, in consultation with the comptroller, to establish a standardized charter-school financial accounting and reporting system and review charter-school fiscal records.",
      "rationale": "Conveys mandatory fiscal-record review but omits its required purpose of ensuring expenditures across school purposes are properly accounted for and safeguarded."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "The commissioner could apply other listed LEA requirements to charter schools that receive state education funding.",
      "rationale": "Conveys the commissioner's discretion to apply the referenced LEA requirements to state-funded charter schools."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "A local board of education would allocate to a charter school local student-generated funds based on the school’s prior-year members",
      "rationale": "Conveys the local board's allocation of local student-generated funding using prior-year charter membership."
    },
    {
      "proposition_id": "P9",
      "status": "partial",
      "summary_quote": "A local board of education would allocate to a charter school local student-generated funds based on the school’s prior-year members, current-year state and local funds above TISA requirements based on those members",
      "rationale": "Captures the funding sources and relevant years but omits the district-average per-pupil calculation."
    },
    {
      "proposition_id": "P10",
      "status": "partial",
      "summary_quote": "A local board of education would allocate to a charter school local student-generated funds based on the school’s prior-year members, current-year state and local funds above TISA requirements based on those members, and funds for current-year members beyond the prior-year count.",
      "rationale": "Conveys funding for membership growth but does not specify that this allocation equals the per-student state and local funds received by the LEA."
    },
    {
      "proposition_id": "P11",
      "status": "full",
      "summary_quote": "It would also allocate appropriate federal funds.",
      "rationale": "Conveys the local board's obligation to allocate appropriate federal funding; the named federal programs are illustrative."
    },
    {
      "proposition_id": "P12",
      "status": "full",
      "summary_quote": "The education department would send the charter school state student-generated funds based on prior-year members.",
      "rationale": "Conveys direct department allocation of state student-generated funding based on prior-year charter membership."
    },
    {
      "proposition_id": "P13",
      "status": "partial",
      "summary_quote": "An LEA would provide federal funds to charter schools it authorizes through agreed shared services or sub-grants based on eligible students, under department procedures.",
      "rationale": "Includes the authorized-school limitation, distribution methods, and department procedures, but omits the requirement that sub-grants represent the school's equitable share of the federal grant."
    },
    {
      "proposition_id": "P14",
      "status": "partial",
      "summary_quote": "Each LEA would include its calculated per-student local payment to charter schools in its upcoming budget and use that amount for allocations.",
      "rationale": "Conveys budget disclosure of the per-pupil amount and its use for allocations, but omits the obligation to include all required calculations in the budget."
    },
    {
      "proposition_id": "P15",
      "status": "partial",
      "summary_quote": "It would pay expected local funds in at least nine equal installments",
      "rationale": "Conveys the minimum number and equality of installments, but omits distribution in the same manner as state funds."
    },
    {
      "proposition_id": "P16",
      "status": "full",
      "summary_quote": "It would pay expected local funds in at least nine equal installments and adjust payments at least in October, February, and June for changes in revenue, membership, or student services.",
      "rationale": "Includes the mandatory adjustment months and all three grounds for adjustment."
    },
    {
      "proposition_id": "P17",
      "status": "full",
      "summary_quote": "Charter schools would spend funds under their governing bodies’ budgets, as revised, and applicable law.",
      "rationale": "Conveys the budget restriction, governing-body revisions, and applicable legal requirements."
    },
    {
      "proposition_id": "P18",
      "status": "full",
      "summary_quote": "These accounting and wording changes would take effect upon enactment. The funding changes would take effect upon enactment for rulemaking and July 1, 2025, for other purposes.",
      "rationale": "Accurately distinguishes immediate effectiveness for Sections 1 and 3 from the rulemaking and general effective dates for Sections 2 and 4."
    }
  ]
}
